const xml = $json.data || $json.body || '';
const text = (tag) => [...xml.matchAll(new RegExp(`<${tag}[^>]*>([\s\S]*?)</${tag}>`, 'g'))].map(m => m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
const esc = s => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const blocks = xml.match(/<PubmedArticle>[\s\S]*?<\/PubmedArticle>/g) || [];
const articles = blocks.map(block => {
  const get = tag => esc((block.match(new RegExp(`<${tag}[^>]*>([\s\S]*?)</${tag}>`)) || [,''])[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
  const pmid = get('PMID');
  const pmc = (block.match(/<ArticleId IdType=\"pmc\">([^<]+)/i) || [,''])[1];
  const doi = (block.match(/<ArticleId IdType=\"doi\">([^<]+)/i) || [,''])[1];
  return { pmid, title: get('ArticleTitle'), abstract: get('AbstractText'), journal: get('Title'), doi, pmc, pubmedUrl: `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`, pdfUrl: pmc ? `https://www.ncbi.nlm.nih.gov/pmc/articles/${pmc}/pdf/` : null, pdfNote: pmc ? 'PMC PDF available; open the PDF and capture its first page.' : 'No PMC identifier in PubMed; a free PDF may not be available.' };
});
const source = articles.map((a, i) => `\n[${i + 1}] ${a.title}\nPMID: ${a.pmid}; Journal: ${a.journal}; DOI: ${a.doi || 'n/a'}\nAbstract: ${a.abstract || 'not supplied'}`).join('\n');
return [{ json: { articles, count: articles.length, source, model: $input.first().json.model || $env.N8N_INSTANCE_AI_MODEL || $env.AGENTIC_DEFAULT_MODEL || 'qwen3.8:27b' } }];

const dossier = $('Build publication dossier').first().json;
const content = $json.choices?.[0]?.message?.content || 'La synthèse IA n’a pas été générée. Vérifiez le modèle, /v1/models et les logs ollama-gate.';
return [{ json: { generatedAt: new Date().toISOString(), period: 'last 14 days', count: dossier.count, synthesis: content, publications: dossier.articles, pdfScreenshotInstruction: 'Pour chaque publication avec pdfUrl, ouvrir le PDF et enregistrer une capture de sa première page. Les articles sans pmc n’ont pas nécessairement de PDF libre.', aiError: $json.error || null } }];
